package scan

import (
	"encoding/json"
	"testing"
)

// parsedMap unmarshals a document's parsed RawMessage into a map for assertions.
// Test helper.
func parsedMap(t *testing.T, doc map[string]any) map[string]any {
	t.Helper()
	raw, ok := doc["parsed"].(json.RawMessage)
	if !ok {
		t.Fatalf("doc has no json.RawMessage parsed: %T", doc["parsed"])
	}
	var m map[string]any
	if err := json.Unmarshal(raw, &m); err != nil {
		t.Fatalf("unmarshal parsed: %v", err)
	}
	return m
}

// TestAssembleBaseDoc_StampAbsolutePath covers B01 (absolute_path stamped into
// parsed for every item), B02 (existing parsed keys + the rest of the document are
// unchanged — purely additive), and B05 (the stamp is generic: a TV item is
// stamped identically, no media-type branch).
func TestAssembleBaseDoc_StampAbsolutePath(t *testing.T) {
	tests := []struct {
		name       string
		moduleType string
		rootPath   string
		rel        string
		parsedJSON string
		wantAbs    string // "" => expect the key absent
	}{
		{
			name:       "image_item_stamped",
			moduleType: "image",
			rootPath:   "/tmp/lib",
			rel:        "sub/IMG.jpg",
			parsedJSON: `{"relative_path":"sub/IMG.jpg","extension":".jpg"}`,
			wantAbs:    "/tmp/lib/sub/IMG.jpg",
		},
		{
			// B05: a TV item is stamped identically — scan is media-type-agnostic.
			name:       "tv_item_also_stamped_no_branch",
			moduleType: "tv",
			rootPath:   "/library/tv",
			rel:        "Show/S01E01.mkv",
			parsedJSON: `{"relative_path":"Show/S01E01.mkv","extension":".mkv"}`,
			wantAbs:    "/library/tv/Show/S01E01.mkv",
		},
		{
			// Boundary: an empty rootPath stamps nothing (the test-only no-stamp
			// path; production always passes lib.RootPath).
			name:       "empty_root_no_stamp",
			moduleType: "image",
			rootPath:   "",
			rel:        "a.png",
			parsedJSON: `{"relative_path":"a.png","extension":".png"}`,
			wantAbs:    "",
		},
	}
	for _, tc := range tests {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			f := mkFile("fid", tc.rel, nil, nil)
			id := mkIdentified("fid", tc.parsedJSON)
			doc := assembleBaseDoc(f, id, tc.moduleType, 1, tc.rootPath)

			// B02: identity fields + ffprobe handling unchanged.
			if got := doc["file_id"]; got != "fid" {
				t.Errorf("file_id = %v, want fid", got)
			}
			if got := doc["module_type"]; got != tc.moduleType {
				t.Errorf("module_type = %v, want %q", got, tc.moduleType)
			}
			if got := doc["schema_version"]; got != 1 {
				t.Errorf("schema_version = %v, want 1", got)
			}

			m := parsedMap(t, doc)
			// B02: existing parsed keys preserved (additive — nothing dropped).
			if got := m["relative_path"]; got != tc.rel {
				t.Errorf("parsed.relative_path = %v, want %q (must be preserved)", got, tc.rel)
			}
			// B01: absolute_path stamped iff rootPath non-empty.
			gotAbs, hasAbs := m["absolute_path"]
			if tc.wantAbs == "" {
				if hasAbs {
					t.Errorf("parsed.absolute_path = %v, want absent (rootPath empty)", gotAbs)
				}
				return
			}
			if !hasAbs {
				t.Fatal("parsed.absolute_path absent, want it stamped")
			}
			if gotAbs != tc.wantAbs {
				t.Errorf("parsed.absolute_path = %v, want %q", gotAbs, tc.wantAbs)
			}
		})
	}
}

// TestAssembleBaseDoc_DeterministicNoFalseStale covers B03: the absolute_path
// stamp is deterministic for (rootPath, rel), so baseChanged (stale-on-rescan)
// does NOT flag a false-stale for the same file re-scanned, but DOES flag a change
// when either the root or the relative path differs.
func TestAssembleBaseDoc_DeterministicNoFalseStale(t *testing.T) {
	mk := func(root, rel string) map[string]any {
		f := mkFile("fid", rel, []byte(`{"format":{"duration":"120.5"}}`), nil)
		id := mkIdentified("fid", `{"relative_path":"`+rel+`","extension":".mkv"}`)
		return assembleBaseDoc(f, id, "tv", 1, root)
	}
	same := mk("/lib", "Show/S01E01.mkv")
	if baseChanged(marshalDoc(mk("/lib", "Show/S01E01.mkv")), same) {
		t.Fatal("baseChanged = true for an identical re-scan (root+rel same), want false (no false-stale)")
	}
	if !baseChanged(marshalDoc(mk("/other", "Show/S01E01.mkv")), same) {
		t.Error("baseChanged = false for a changed root, want true")
	}
	if !baseChanged(marshalDoc(mk("/lib", "Show/S02E01.mkv")), same) {
		t.Error("baseChanged = false for a changed rel, want true")
	}
}
